<script setup>
import {computed} from 'vue'
import Chart from './Chart.vue'
import {fmt,chartBase,colors} from '../shared'
import {groupAiYears,EARLY_YEAR_BUCKET} from '../helpers/aiYearBuckets'
const props=defineProps({data:Object}),emit=defineEmits(['explore'])
const c=computed(()=>props.data.study.contribution),m=computed(()=>props.data.currentInventory?{fund_papers:props.data.currentInventory.fund_paper_summary.papers,fund_projects:props.data.currentInventory.fund_paper_summary.projects,fund_paper_edges:props.data.currentInventory.counts.ai_fund_papers}:c.value.source_metrics),s=computed(()=>c.value.reviewed_sample)
const groupedYears=computed(()=>groupAiYears(props.data.currentInventory?props.data.currentInventory.fund_paper_years.filter(r=>r.publication_year!=null).map(r=>({year:r.publication_year,count:r.papers})):(c.value.years||[])))
const years=computed(()=>({...chartBase,grid:{top:20,left:55,right:20,bottom:35,containLabel:true},tooltip:{trigger:'axis'},xAxis:{type:'category',data:groupedYears.value.map(r=>String(r.year)),axisLabel:{fontSize:12,interval:0,hideOverlap:false,showMinLabel:true,showMaxLabel:true,rotate:50,margin:13,lineHeight:18,formatter:value=>value===EARLY_YEAR_BUCKET?'2016年之前':value},axisLine:{lineStyle:{color:'#d9dde5'}}},yAxis:{type:'value',splitLine:{lineStyle:{color:'#eee9ed',type:'dashed'}}},series:[{type:'bar',name:'资助论文',barMaxWidth:25,itemStyle:{color:colors[0],borderRadius:[4,4,0,0]},data:groupedYears.value.map(r=>r.count)}]}))
const selectedTopics=computed(()=>c.value.by_topic)
const shared=computed(()=>selectedTopics.value.filter(t=>t.patents>0))
</script>
<template><section class="panel fund-hero"><div><p class="eyebrow">基金贡献度 · 人工智能</p><h2>基金投入如何支撑技术发展？</h2><p>从资助成果追到研究方法，再沿技术主题观察专利中的应用线索。</p><div class="case-tags"><span>支撑范围</span><span>学术影响</span><span>技术应用</span></div></div><div class="fund-kpis"><article><strong>{{fmt(m.fund_papers)}}</strong><span>国自然关联论文</span></article><article><strong>{{fmt(m.fund_projects)}}</strong><span>关联基金项目</span></article><article><strong>{{fmt(m.fund_paper_edges)}}</strong><span>项目—论文连接</span></article><article><strong>{{s.topics}}</strong><span>已核验技术主题</span></article></div></section><div class="fund-dimensions"><article :style="{'--tone':colors[0]}"><h3>支撑范围</h3><p>连接 <strong>{{fmt(m.fund_projects)}}</strong> 个项目与 <strong>{{fmt(m.fund_papers)}}</strong> 篇人工智能相关论文。</p><p>技术样本覆盖 <strong>{{s.categories}}</strong> 个大类，已形成 <strong>{{s.triples}}</strong> 组可追溯的基金—论文—技术连接。</p></article><article :style="{'--tone':colors[1]}"><h3>学术影响</h3><p>从代表论文、研究方法与技术脉络，追踪基础研究的知识积累。</p><router-link to="/evolution">查看代表论文与演进综述 →</router-link><p v-if="data.currentInventory" class="muted">关联库已建立 {{fmt(data.currentInventory.counts.citation_edge)}} 对论文引用关系。</p></article><article :style="{'--tone':colors[2]}"><h3>技术应用</h3><p v-if="shared.length">资助论文与专利文本在 <strong>{{shared.map(t=>t.name).join('、')}}</strong> 等主题汇合，可进一步追踪具体采用证据。</p><p v-else>沿共同技术主题，探索研究成果与专利文本的关联。</p><button class="button secondary" @click="emit('explore','mixed')">探索多链关系 →</button></article></div><div class="two-columns"><section class="panel"><div class="panel-heading"><h3>关联论文年度分布</h3><span>篇</span></div><Chart :option="years" :height="265" label="人工智能资助论文年份分布"/></section><section class="panel"><div class="panel-heading"><h3>基金支持的技术样本</h3><span>已核验连接</span></div><div class="fund-topic-scroll"><table class="fund-topic-table"><thead><tr><th>技术主题</th><th>项目</th><th>论文</th><th>同主题专利样本</th></tr></thead><tbody><tr v-for="t in selectedTopics" :key="t.id"><td><router-link :to="{path:'/evolution',query:{topic:t.id}}">{{t.name}} ↗</router-link></td><td>{{t.projects}}</td><td>{{t.papers}}</td><td>{{t.patents}}</td></tr></tbody></table></div></section></div><section class="panel"><div class="panel-heading"><h3>从基金项目追到研究方法</h3><button class="button secondary" @click="emit('explore','fund_paper')">打开交互证据图 →</button></div><div class="fund-topic-scroll"><table class="fund-topic-table"><thead><tr><th>基金项目 · 批准号</th><th>成果论文</th><th>技术主题</th></tr></thead><tbody><tr v-for="e in c.examples" :key="e.paper.id"><td><div v-for="f in e.funds" :key="f.id">{{f.label}}<br/><small>{{f.fields['批准号']}} · {{f.fields['依托单位']}}</small></div></td><td>{{e.paper.label}}<br/><small>{{e.paper.year||''}}</small></td><td>{{e.topics.map(t=>t.label).join('、')}}</td></tr></tbody></table></div></section></template>
